import { FormEvent, useEffect, useState } from 'react'

interface IBMArchiveJobSummary {
  job_id: string
  backend: string | null
  created: string | null
  status: string | null
  program: string | { id?: string } | null
  cost: number | null
  tags: string[]
  shots: number | null
  classical_bits: number | null
  qpy_version: string | null
  result_schema: string | null
  result_dtype: string | null
  result_shape: number[]
  has_circuit_payload: boolean
}

interface IBMArchiveJobDetail extends IBMArchiveJobSummary {
  archive_dir: string
  info_file: string
  result_file: string
  notes: string[]
}

interface IBMArchiveListResponse {
  jobs: IBMArchiveJobSummary[]
  archive_dir?: string | null
}

interface IBMArchiveDetailResponse {
  job: IBMArchiveJobDetail
}

function formatProgram(program: IBMArchiveJobSummary['program']) {
  if (!program) {
    return 'n/a'
  }

  if (typeof program === 'string') {
    return program
  }

  return program.id || 'structured program metadata'
}

function formatWhen(timestamp: string | null) {
  if (!timestamp) {
    return 'n/a'
  }

  const parsed = new Date(timestamp)
  if (Number.isNaN(parsed.getTime())) {
    return timestamp
  }

  return parsed.toLocaleString()
}

export default function ArchiveView() {
  const [archiveDir, setArchiveDir] = useState('')
  const [jobs, setJobs] = useState<IBMArchiveJobSummary[]>([])
  const [selectedJobId, setSelectedJobId] = useState('')
  const [selectedJob, setSelectedJob] = useState<IBMArchiveJobDetail | null>(null)
  const [loadingList, setLoadingList] = useState(false)
  const [loadingDetail, setLoadingDetail] = useState(false)
  const [error, setError] = useState('')

  const buildQuery = (path: string) => {
    const trimmed = path.trim()
    return trimmed ? `?archive_dir=${encodeURIComponent(trimmed)}` : ''
  }

  const loadJobs = async (path: string) => {
    setLoadingList(true)
    setError('')

    try {
      const res = await fetch(`/archives/ibm/jobs${buildQuery(path)}`)
      const data = (await res.json()) as IBMArchiveListResponse | { detail?: string }

      if (!res.ok) {
        throw new Error('detail' in data ? data.detail || 'Failed to load archive jobs' : 'Failed to load archive jobs')
      }

      const response = data as IBMArchiveListResponse
      setJobs(response.jobs)

      if (response.jobs.length > 0) {
        setSelectedJobId((current) => {
          const next = current && response.jobs.some((job) => job.job_id === current)
            ? current
            : response.jobs[0].job_id
          return next
        })
      } else {
        setSelectedJobId('')
        setSelectedJob(null)
      }

      window.localStorage.setItem('qpyth-archive-dir', path.trim())
    } catch (fetchError) {
      console.error(fetchError)
      setJobs([])
      setSelectedJobId('')
      setSelectedJob(null)
      setError(fetchError instanceof Error ? fetchError.message : 'Failed to load IBM archive jobs.')
    } finally {
      setLoadingList(false)
    }
  }

  useEffect(() => {
    const saved = window.localStorage.getItem('qpyth-archive-dir') || ''
    setArchiveDir(saved)
    loadJobs(saved)
  }, [])

  useEffect(() => {
    if (!selectedJobId) {
      return
    }

    const loadDetail = async () => {
      setLoadingDetail(true)

      try {
        const res = await fetch(`/archives/ibm/jobs/${selectedJobId}${buildQuery(archiveDir)}`)
        const data = (await res.json()) as IBMArchiveDetailResponse | { detail?: string }

        if (!res.ok) {
          throw new Error('detail' in data ? data.detail || 'Failed to load archive job detail' : 'Failed to load archive job detail')
        }

    setSelectedJob((data as IBMArchiveDetailResponse).job)
  } catch (fetchError) {
    console.error(fetchError)
    setSelectedJob(null)
    setError(fetchError instanceof Error ? fetchError.message : `Failed to load archive job ${selectedJobId}.`)
  } finally {
    setLoadingDetail(false)
  }
}

